// Edges 结构体表示图的边
type Edges struct {
	Node string
	Cost int
}

// Item 是优先队列中的元素
type Item struct {
	Node     string // 节点名称
	Priority int    // 优先级（路径成本）
	Index    int    // 在堆中的索引
}

// PriorityQueue 优先队列实现
type PriorityQueue []*Item

func (pq *PriorityQueue) Len() int { return len(*pq) }

func (pq *PriorityQueue) Less(i, j int) bool {
	return (*pq)[i].Priority < (*pq)[j].Priority
}

func (pq *PriorityQueue) Swap(i, j int) {
	(*pq)[i], (*pq)[j] = (*pq)[j], (*pq)[i]
	(*pq)[i].Index = i
	(*pq)[j].Index = j
}

func (pq *PriorityQueue) Push(x interface{}) {
	n := len(*pq)
	item := x.(*Item)
	item.Index = n
	*pq = append(*pq, item)
}

func (pq *PriorityQueue) Pop() interface{} {
	old := *pq
	n := len(old)
	item := old[n-1]
	old[n-1] = nil  // 避免内存泄漏
	item.Index = -1 // 标记为已移除
	*pq = old[0 : n-1]
	return item
}

// Dijkstra 实现Dijkstra最短路径算法
func Dijkstra(graph map[string]map[string]int, start, end string) ([]string, int) {

	var (
		// 初始化距离和前驱节点
		distances = make(map[string]int, 3)
		previous  = make(map[string]string, 3)
		nodes     = make(map[string]struct{}, 5)

		//
		path = make([]string, 0, 3)
	)

	if _, exists := graph[start]; !exists {
		return nil, 0
	}

	// 检查终点是否存在
	if _, exists := graph[end]; !exists {
		return nil, 0
	}

	// 初始化所有节点
	for node := range graph {
		distances[node] = math.MaxInt32
		previous[node] = ""
		nodes[node] = struct{}{}
	}
	distances[start] = 0

	// 初始化优先队列
	pq := make(PriorityQueue, 0)
	heap.Init(&pq)
	heap.Push(&pq, &Item{
		Node:     start,
		Priority: 0,
	})

	for pq.Len() > 0 {
		currentItem := heap.Pop(&pq).(*Item)
		currentNode := currentItem.Node

		// 找到目标节点
		if currentNode == end {
			break
		}

		// 遍历邻居节点
		for neighbor, cost := range graph[currentNode] {
			alt := distances[currentNode] + cost
			if alt < distances[neighbor] {
				distances[neighbor] = alt
				previous[neighbor] = currentNode
				heap.Push(&pq, &Item{
					Node:     neighbor,
					Priority: alt,
				})
			}
		}
	}

	// 构建路径
	current := end
	for current != "" && current != start {
		path = append([]string{current}, path...)
		current = previous[current]
		if current == "" {
			return nil, 0 // 不可达
		}
	}
	path = append([]string{start}, path...)

	return path, distances[end]
}

